:root {
  --bg-card: #0f1117;
  --bg-row-alt: #181c27;
  --bg-header-row: #1e2333;
  --border: #2a2f42;
  --text-primary: #e8eaf0;
  --text-secondary: #7b82a0;
  --text-header: #4a5170;
  --accent-up: #22c97a;
  --accent-down: #f04f5e;
  --accent-neutral: #7b82a0;
  --badge-up-bg: #0d3325;
  --badge-up-text: #22c97a;
  --color-btc: #f7931a;
  --color-eth: #627eea;
  --color-sol: #9945ff;
  --color-usdc: #2775ca;
}

.portfolio-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  width: 500px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
}

.total-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
}

.badge {
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
}

.badge--up {
  background: var(--badge-up-bg);
  color: var(--badge-up-text);
}

.assets-grid {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}

.asset-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  align-items: center;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
}

.asset-row:last-child {
  border-bottom: none;
}

.asset-row--header {
  background: var(--bg-header-row);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-header);
}

.asset-row:not(.asset-row--header):nth-child(even) {
  background: var(--bg-row-alt);
}

.asset-name {
  display: flex;
  align-items: center;
  gap: 8px;
}

.coin-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.coin-dot--btc { background: var(--color-btc); }
.coin-dot--eth { background: var(--color-eth); }
.coin-dot--sol { background: var(--color-sol); }
.coin-dot--usdc { background: var(--color-usdc); }

.coin-symbol {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.coin-label {
  font-size: 12px;
  color: var(--text-secondary);
}

.price {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
}

.change {
  font-size: 13px;
  font-weight: 600;
}

.change--up { color: var(--accent-up); }
.change--down { color: var(--accent-down); }
.change--neutral { color: var(--accent-neutral); }

.holding {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.card-footer {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bar-wrap {
  display: flex;
  width: 100%;
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
  gap: 2px;
}

.bar-segment {
  height: 100%;
  border-radius: 2px;
}

.bar-seg--btc { background: var(--color-btc); width: 57%; }
.bar-seg--eth { background: var(--color-eth); width: 28%; }
.bar-seg--sol { background: var(--color-sol); width: 9%; }
.bar-seg--usdc { background: var(--color-usdc); width: 6%; }

.legend {
  display: flex;
  gap: 14px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
}

.legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  flex-shrink: 0;
}

.legend-dot--btc { background: var(--color-btc); }
.legend-dot--eth { background: var(--color-eth); }
.legend-dot--sol { background: var(--color-sol); }
.legend-dot--usdc { background: var(--color-usdc); }
